import json,pathlib
b={'start':1620,'end':1710,'decisions':{}}
def c(i,t,r):b['decisions'][str(i)]={'decision':'change','target':t,'reason':r}
c(1620,'<ffx:wonder>تفقدت المنطقة وأنت في الداخل...<ffx:neutral>','look around تفقد ما حول المتكلمة لا حول أرتيوم المخاطب.')
c(1628,'<ffx:wide_smile>حظًا موفقًا!<ffx:neutral>','Break a leg تمني التوفيق لا إصابة ساق.')
c(1630,'<ffx:anger>الكنيسة هناك!<ffx:disgust_light> التفت نحوها واركض، أسرع!<ffx:neutral>','Face that way التوجه نحو الكنيسة لا واجه بهذه الطريقة.')
c(1631,'<ffx:smile_light>لا أصدق أن ابنتي تزوجت هذا الرجل...<ffx:smile> جنون!<ffx:neutral>','To think تعجب مما وقع فعلًا لا تخمين حصول الزواج.')
c(1633,'كفى! لن تحصل على شيء هذا الأسبوع!','Thats it سخط آنا، مع حفظ التلميح دون تحويله إلى معنى صريح مضاف.')
c(1634,'الآن غضبت حقًا يا أرتيوم! أطالب بالطلاق!','تصحيح تأنيث آنا وإزالة رسميًا الحرفية في مزاح الزوجة.')
c(1637,'لقد سئمت يا أرتيوم. سأنتظر عند برج الكهرباء. عد حين تكتفي من التجول، واستعد لتوبيخ أبي!','I have had it سئمت لا لقد كان، وتصحيح أمر العودة وchewed out توبيخ لا مضغ.')
c(1640,'أرى أناسًا في الكنيسة، ولا يبدو أن أحدًا مسلح. الأفضل أن نتقدم إليهم علانية.','open approach اقتراب علني لا النهج المفتوح المجرد.')
c(1644,'<ffx:wonder>بدأ أبونا المقدس سيلانتيوس موعظته،<ffx:smile> فادخل الهيكل لتبصر نور الحق...<ffx:smile_light>','تصحيح فعل إبصار نور الحق ولقب الأب المقدس دون إضافة قداسة رسمية كاسم.')
c(1645,'<ffx:wonder>نحن قوم مسالمون،<ffx:smile_light> فلا تشهر سلاحك، من فضلك.','weapons sheathed عدم إشهار السلاح لا تغليف أسلحة بأغلفة.')
c(1647,'<ffx:wonder_strong>اصعد إلى هنا!<ffx:wonder_light>','استعادة اتجاه الصعود.')
c(1651,'<ffx:anger>سيصل إخوتنا المقاتلون قريبًا،<ffx:smile> ويقام عدل الرب!<ffx:neutral>','brothers militant مقاتلو الطائفة لا مناضلون سياسيون.')
c(1652,'<ffx:anger>فليطردوا كاتيا ونسلها أيضًا!<ffx:neutral>','spawn نسل على سبيل الازدراء لا فعل تفرخ.')
c(1655,'<ffx:smile>نعم! إنها أملنا الوحيد!<ffx:neutral>','الضمير عائد إلى عدالة الرب المؤنثة في السياق.')
c(1656,'<ffx:smile>حكم سريع وعادل! أقيموا عدل الرب!<ffx:neutral>','sentence حكم قضائي لا جملة لغوية، وإصلاح أمر إقامة العدل.')
c(1657,'<ffx:smile>فلا نخش الزنادقة ولا ظل الموت!<ffx:wonder_strong> فنحن جميعًا في يد ربنا!<ffx:neutral>','توحيد heretics إلى الزنادقة وصياغة الوعظ دون حرفية دعونا.')
c(1658,'<ffx:wonder_strong>وإن أفلت بعض الزنادقة من حراستنا اليقظة،<ffx:smile_light> فستلتهمهم سمكة القيصر!<ffx:wonder_light>','vigil حراسة يقظة لا وقفة احتجاجية، مع حفظ الوعيد.')
c(1659,'<ffx:wonder_strong>فلنناديها الآن!<ffx:wonder_light>','call for استدعاء سمكة القيصر لا الدعاء لها بحاجات، وإحالة مؤنثة للاسم.')
for i in range(1660,1665):c(i,'<ffx:fear>تعالي يا سمكة القيصر!<ffx:fear_light>','تصحيح أمر المؤنث العائد إلى الاسم المعتمد سمكة القيصر.')
c(1665,'<ffx:wonder_strong>فلنتوسل إليها أن تحمينا!<ffx:wonder_light>','توسل طلب حماية لا حماية السمكة نفسها، وتأنيث الإحالة العربية.')
for i in range(1666,1671):c(i,'<ffx:fear>احمينا يا سمكة القيصر!<ffx:fear_light>','تصحيح أمر الحماية المؤنث مع إبقاء اسم سمكة القيصر.')
c(1671,'<ffx:disgust_strong>وبتحريض من الشيطان ابتكرت البشرية التقنية سعيًا إلى التجديف والدمار،<ffx:fear_strong> تعمل كلها بالكهرباء، أنفاس الشيطان السامة!<ffx:fear_light>','توحيد التقنية وصقل النبرة الوعظية وحفظ ادعاء الطائفة لا تقرير حقيقة خارجه.')
c(1672,'<ffx:wonder_strong>ورأيت رؤيا ألهمني إياها الرب،<ffx:fear> رؤيا عقاب إلهي على خطايا الكهرباء والتقنية الآثمة!<ffx:fear_light>','الرؤيا الدينية لا رؤية عادية، وتوحيد التقنية وصياغة الإلهام.')
c(1673,'<ffx:smile_strong>وحدث ما رأيته في الرؤيا!<ffx:fear> ولقي الخطاة مصيرًا جهنميًا بسبب ما ابتكروه!<ffx:fear_light>','الرؤيا للمتكلم لا لما تصوره غائب، واستعادة سبب العقاب من صنع البشر.')
c(1674,'<ffx:wonder_strong>ثم رأيت رؤيا جديدة! هكذا يقول الرب!<ffx:wonder_light>','توحيد رؤيا وصياغة الإعلان النبوي.')
for i in range(1681,1687):
 tag='wonder_strong' if i==1681 else 'fear'
 end='wonder_light' if i==1681 else 'fear_light'
 c(i,f'<ffx:{tag}>التقنية خطيئة!<ffx:{end}>','توحيد Technology إلى التقنية وإعادة الوسم إلى بداية القول.')
c(1687,'<ffx:smile>ونحن الأبرار، أحباء الرب،<ffx:wonder_strong> نجونا بمشيئته في ديرنا،<ffx:smile_light> لأننا قاومنا<ffx:anger> إغواء الشيطان وصددناه!<ffx:wonder_light>','تصحيح محبوبِي الرب المجرورة في خبر نحن وصقل ادعاء النجاة بالمقاومة.')
c(1688,'<ffx:wonder_strong>ورأيت رؤيا أخرى عن شياطين العدو التي<ffx:fear_strong> تقتل وتشوه بكهربائها، وعن أعوانه القادمين على صهوة جواد من حديد<ffx:disgust> ليفسدوا الأبرار بأكاذيبهم! وعن حارس للمياه،<ffx:wonder_strong> سمكة القيصر، يرسل إلينا ليذكرنا بواجبنا!<ffx:wonder_light>','الشياطين تقتل البشر لا العكس؛ إصلاح انقلاب الفاعل والمفعول والفاصلة المكررة مع حفظ صور الوعظ.')
c(1689,'<ffx:fear>وامتلأت الغابات بشياطين الكهرباء، وهلك كثير من ضعفاء الإيمان!<ffx:sadness> والتهمت سمكة القيصر مرتدين كثيرين،<ffx:wonder> فرسخ الإيمان في قلوبنا!','their faith إيمان أصحاب القلوب لا إيمان طرف آخر؛ حفظ دعوى الرسوخ لا القسوة.')
c(1690,'فلنصد الإغواء أيها الإخوة،<ffx:smile> ولنقبل بنفوسنا على الصلاة!<ffx:fear_strong> ولينزل غضب الرب على الخطاة والشياطين كما كان دائمًا،<ffx:wonder_strong> وليرث الأبرار النعيم الأبدي إلى أبد الآبدين، آمين!<ffx:wonder_light>','تصحيح فعل الإقبال على الصلاة بدل مصدر تحويل المنفصل.')
c(1691,'<ffx:anger>وإن جاء الزنادقة ليقتلونا، فسنظل صامدين!<ffx:wonder_light>','come for our lives يقصد سلب الحياة لا إنقاذها؛ توحيد الزنادقة.')
c(1693,'<ffx:fear_strong>وسينتقم ربنا لهؤلاء الشهداء،<ffx:disgust> فمن يقتل أحد المؤمنين ملعون إلى الأبد!<ffx:wonder_light>','حفظ تعليل اللعنة الأبدية دون إضافة خالدًا فيه ذات المرجع غير المذكور.')
c(1696,'<ffx:disgust>أكاذيب كادت تبيد البشرية!<ffx:fear_light>','all but eradicated كادت تبيد لا أبيدت البشرية بالكامل.')
c(1698,'<ffx:disgust>كلكم أشرار!<ffx:anger> لا تنقذون أحدًا!<ffx:anger_light>','تصحيح مخاطب الجمع في الشطر الثاني.')
c(1700,'<ffx:disgust>نسل الشيطان...<ffx:fear_light>','spawn نسل لا فعل تفرخ.')
c(1703,'<ffx:disgust_strong>تلك الساحرة الملعونة...<ffx:anger> وأمها الكلبة أيضًا!<ffx:fear_light>','dog of a mother إهانة الأم لا كلب تملكه.')
c(1704,'<ffx:disgust>أنجاس، موسومون بالكهرباء...<ffx:fear_light>','marked وصمة في اعتقادهم لا تميز إيجابي بالكهرباء.')
c(1706,'<ffx:anger>انفها، ليكون ذلك درسًا لهم!<ffx:fear_light>','Banish نفي وسيرى الباقون العقوبة درسًا لا مجرد فعل تعليم مبهم.')
c(1707,'<ffx:anger>نعم! إنهم لا يستحقون حماية سمكة القيصر!<ffx:fear_light>','توحيد اسم وحش الحماية المفرد لا أسماك متعددة.')
c(1709,'<ffx:disgust>انفوهم! احملوهم على التوبة!<ffx:fear_light>','إصلاح المصدر نفيهم إلى فعل أمر وطبيعة الإكراه الوعظي.')
(pathlib.Path(__file__).parent/'batch_1620.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
